import os
import shutil

def organize_files(directory_path):
    if not os.path.exists(directory_path):
        print("Directory does not exist.")
        return

    for filename in os.listdir(directory_path):
        file_path = os.path.join(directory_path, filename)

        if os.path.isfile(file_path):
            file_extension = os.path.splitext(filename)[1].lower()
            if file_extension == '':
                file_extension = 'no_extension'

            extension_directory = os.path.join(directory_path, file_extension[1:].upper())

            if not os.path.exists(extension_directory):
                os.makedirs(extension_directory)

            shutil.move(file_path, os.path.join(extension_directory, filename))

            print(f"Moved: {filename} -> {extension_directory}")

# Example usage:
# organize_files('/path/to/your/directory')
